// The seven pixel-art Big Bend scenes behind the home page (generated by scripts/pixel-scenes.py).
import { STOP_IDS } from './stops';
export const SCENE_IDS = ['hero', ...STOP_IDS] as const;
export type SceneId = (typeof SCENE_IDS)[number];
export const SCENE_SIZE = { land: { w: 240, h: 135 }, port: { w: 120, h: 214 } } as const;

/** `/scenes/<id>.png` for the landscape set, `/scenes/<id>-m.png` for the portrait set. */
export const sceneUrl = (id: SceneId, set: 'land' | 'port'): string =>
  `/scenes/${id}${set === 'port' ? '-m' : ''}.png`;
